import{_ as a,a as t,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"雅思阅读真经总纲","description":"以定位、同义改写、判断和错题复盘组织雅思阅读导读，并保留具体版次的目录核对边界。","frontmatter":{"title":"雅思阅读真经总纲","description":"以定位、同义改写、判断和错题复盘组织雅思阅读导读，并保留具体版次的目录核对边界。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 语言学习与出国考试 · 雅思备考专项","summary":"以定位、同义改写、判断和错题复盘组织雅思阅读导读，并保留具体版次的目录核对边界。","status":"active","related":[{"title":"雅思词汇真经","link":"/life/personal/books/languages/ielts-vocabulary","kind":"书籍导读","scope":"general","audience":"general"},{"title":"雅思口语真经总纲","link":"/life/personal/books/languages/ielts-speaking","kind":"书籍导读","scope":"general","audience":"general"}],"prev":false,"next":{"text":"雅思词汇真经","link":"/life/personal/books/languages/ielts-vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"雅思词汇真经","link":"/life/personal/books/languages/ielts-vocabulary"}},"headers":[],"relativePath":"life/personal/books/languages/ielts-reading.md","filePath":"life/personal/books/languages/ielts-reading.md"}'),l={name:"life/personal/books/languages/ielts-reading.md"};function n(s,e,i,d,h,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="雅思阅读真经总纲" tabindex="-1">雅思阅读真经总纲 <a class="header-anchor" href="#雅思阅读真经总纲" aria-label="Permalink to &quot;雅思阅读真经总纲&quot;">​</a></h1><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p><strong>分类：语言学习与出国考试 → 雅思备考专项。</strong> 这本书在书单中承担阅读方法与题型训练的角色。学习目标应是理解题目要求、识别原文证据并稳定作答，而不是用某个技巧绕过文本理解。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p><strong>《雅思阅读真经总纲》：可核书目作者为刘洪波。</strong> <a href="https://m.dushu.com/book/12597913/" target="_blank" rel="noopener noreferrer">2013年版书目</a>列出中国人民大学出版社、ISBN 9787300171142；另有题名带“最新”的后续版。<a href="https://www.guixue.com/p/ielts/fourlectures/h5.html" target="_blank" rel="noopener noreferrer">学为贵讲座页面</a>可确认其雅思培训背景。作者的相关经验来自考试教学与教材编写，不代表 IELTS 官方立场，宣传称谓不作为权威依据。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合已有基础阅读能力、想改进定位与错题分析的雅思考生。如果主要问题是长句和词汇，需同步精读；如果只在计时条件下失误，可把方法用于限时训练复盘。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>已核到刘洪波编著的2013年版，也有后续“最新”版；用户所持ISBN未指定。<strong>具体版次待确认；以下保留本站主题导读，不是原书目录。</strong> 题型分法、训练顺序和例题编号以实物为准。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题导读</th><th>学习重点</th><th>复盘方法</th></tr></thead><tbody><tr><td>文章结构与定位</td><td>区分主旨、论据、例子和转折，不把找到同一个词当作找到答案。</td><td>给每段写一句功能说明，并标出证据位置。</td></tr><tr><td>同义改写</td><td>识别题干与原文之间的词汇替换、语态变化及概括关系。</td><td>将题干表达与原文证据成对记录。</td></tr><tr><td>判断题</td><td>区分原文支持、原文矛盾和信息不足，避免用常识补足缺失内容。</td><td>写出判断依据，特别说明为什么不是“未提及”。</td></tr><tr><td>匹配与标题题</td><td>辨认段落中心，处理多个候选项之间的范围和细节差异。</td><td>为每个排除项写出一个明确理由。</td></tr><tr><td>填空与简答</td><td>同时检查意思、语法位置、拼写和题目字数限制。</td><td>把“理解错误”与“答案形式错误”分别统计。</td></tr><tr><td>限时训练</td><td>在准确率与阅读速度之间找到适合自己的节奏。</td><td>保留定位、理解、选择各环节的耗时与错误类型。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p><strong>本站阅读评析：</strong> 技巧真正有用的地方，是帮助读者更快找到证据，而不是把复杂题目变成词语对号入座。错题记录如果只写正确答案，很难解释下一次为什么仍然会错。更有效的复盘是写清“我依据了什么、原文实际说了什么、两者在哪里分叉”。</p><p>这本书适合作为方法工具，与完整文章阅读和官方样题配合。是否掌握一种方法，应由未见过的文本验证。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><p><strong>本站原创阅读提炼，不是原书引用：</strong> 定位帮助找到证据，理解决定证据究竟支持什么。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p><strong>本站阅读评析，非书单提供者亲历：</strong> 为错题留下题干、证据句、同义改写和误判原因，特别区分原文矛盾与原文未说明。用没做过的文章检验方法，避免把记住例题当成掌握能力。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>方法归纳能减少无目的浏览，但只寻找关键词容易忽略否定、比较与限定条件。不同版次的例题和呈现方式也需核对。<strong>推荐语：</strong> 适合把阅读技巧变成证据核对流程，每读一节就用新题检查。</p><h2 id="来源或核对入口" tabindex="-1">来源或核对入口 <a class="header-anchor" href="#来源或核对入口" aria-label="Permalink to &quot;来源或核对入口&quot;">​</a></h2><ul><li><a href="https://ielts.org/take-a-test/test-types" target="_blank" rel="noopener noreferrer">IELTS 官方考试介绍</a>：核对当前考试类型与要求。</li><li><a href="https://search.worldcat.org/search?q=%E9%9B%85%E6%80%9D%E9%98%85%E8%AF%BB%E7%9C%9F%E7%BB%8F%E6%80%BB%E7%BA%B2" target="_blank" rel="noopener noreferrer">WorldCat 题名检索</a>：核对版次；本页不把检索结果当作已确认目录。</li></ul><p><a href="./../overview">返回书单总览</a></p>',23)])])}const g=a(l,[["render",n]]);export{u as __pageData,g as default};
